import React, { forwardRef } from "react";
import { clsx } from "clsx";

import { useMenu } from "../hooks/use-menu";
import { MenuClasses } from "../menu.styles";

const MenuDivider = forwardRef<HTMLDivElement, React.ComponentPropsWithoutRef<"div">>(
  ({ children, className, ...props }, ref) => {
    const { RadixComponent } = useMenu();
    return (
      <RadixComponent.Separator
        ref={ref}
        className={clsx(MenuClasses.divider, className)}
        {...props}
      >
        {children}
      </RadixComponent.Separator>
    );
  },
);
MenuDivider.displayName = "Menu.Divider";

export { MenuDivider };
